dir:

















  &DefaultButton;




function filter$sysunit(p){
  this.constructor(p);
}
filter$sysunit.prototype = new DirEvent();
filter$sysunit.prototype.afterInit = function(){
  var p = this._dir;
}
filter$sysunit.prototype.beforeButtonDialogClick = function (id) {
  var p = this._dir;
  if (id == 'filterOk') {
    var time = $.userinfo.val('CommandTimeout');
    p.wait(true);
    $.invoke('SetUnit', { iUnit: p.valForm('unit_id') }, this, time, function (d) {
      $.clearClientCache();
      p.wait(false);
      if (d == null) {
        $.alert(p.msg('errorSelectUnit'));
        return;
      }
      d = new DataRow(d);
      $.userinfo.val('unit_id', d.val("unit_id"));
      $("#header").sysmenu("setUnit", d.val("ma_unit"), d.val("ten_unit"));
      p._close();
    })
    return false;
  }
  return true;
}








if 1 = (select count(1) from dbo.ISWIFTFunctionGetUnitIDRight(@@userId, @@admin, '')) begin
  select '$OnlyOneUnitRight' as pauseToast
  return
end
select 'p.field(''unit_id'').valueDefault = ''@@unit''' as script
